// Local development defaults — production uses runtime-env.js generated from template.
//
// OIDC_CLIENT_ID starts as a placeholder: the Logto SPA application id is generated by Logto
// itself (not chosen, unlike the old Keycloak client id). Run infra/logto/bootstrap.mjs after
